#pragma once
#include "editing.hpp"
#include <stdexcept>
namespace vamp {
struct BounceRequest{int track=-1;ClipSelection selection;double first=0,last=0;};
inline BounceRequest makeBounceRequest(const Project&p,const ClipSelection&selection,int track){if(track<0||track>=(int)p.tracks.size())throw std::runtime_error("Select a Playlist track");if(p.tracks.size()>=TrackCount)throw std::runtime_error("Bounce needs one free audio track");auto&t=p.tracks[track];if(t.frozen||t.external)throw std::runtime_error("Unfreeze or record this source before bouncing");BounceRequest request;request.track=track;request.first=16384;for(auto index:selection)if(index.first==track&&index.second>=0&&index.second<(int)t.clips.size()){auto&clip=t.clips[index.second];request.selection.insert(index);request.first=std::min(request.first,clip.beat);request.last=std::max(request.last,clip.beat+clip.length);}if(request.selection.empty()||request.last<=request.first)throw std::runtime_error("Select clips to bounce");return request;}
inline Project bounceSnapshot(const Project&p,const BounceRequest&r){auto snapshot=p;std::vector<Clip>clips;for(auto index:r.selection)clips.push_back(p.tracks.at(index.first).clips.at(index.second));snapshot.tracks.at(r.track).clips=std::move(clips);for(int id=0;id<(int)snapshot.tracks.size();id++){auto&t=snapshot.tracks[id];t.solo=false;t.monitor=false;if(id==r.track){t.mute=false;continue;}if(t.output==r.track)t.output=MasterChannel;t.sends.erase(std::remove_if(t.sends.begin(),t.sends.end(),[&](auto&s){return s.target==r.track&&!s.sidechain;}),t.sends.end());}snapshot.master=Track{};snapshot.bars=std::max(snapshot.bars,barsForEnd(r.last));return snapshot;}
// Audio contains source + inserts before the track fader. A clean adjacent lane retains
// the original fader/pan, their automation and outgoing routing, without processing FX twice.
inline int commitBounce(Project&p,const BounceRequest&r,const std::shared_ptr<Sample>&audio){if(!audio||audio->left.empty()||audio->rate<8000||p.tracks.size()>=TrackCount)throw std::runtime_error("Cannot place bounced audio");if(r.first+audioBeatLength(p,r.first,audio->left.size()/double(audio->rate))>16384)throw std::runtime_error("Bounced audio exceeds the song range");auto&source=p.tracks.at(r.track);if(source.frozen||source.external)throw std::runtime_error("Bounce source has changed");for(auto index:r.selection)if(index.first!=r.track||index.second<0||index.second>=(int)source.clips.size())throw std::runtime_error("Bounce selection has changed");Track lane=source;lane.name+=" · Bounce";lane.notes.clear();lane.patterns.clear();lane.activePattern=0;lane.sample.reset();lane.sampler=lane.audioInput=lane.chromatic=lane.monitor=lane.armed=lane.external=lane.frozen=false;lane.freezeAudio.reset();lane.pluginPaths.clear();lane.pluginStates.clear();lane.pluginBypass.clear();lane.slices.clear();lane.solo=false;if(lane.automationTarget==2){lane.automationEnabled=false;lane.automation.clear();}lane.automationLanes.erase(std::remove_if(lane.automationLanes.begin(),lane.automationLanes.end(),[](auto&a){return a.target==2;}),lane.automationLanes.end());Clip clip;clip.beat=r.first;clip.length=audioBeatLength(p,clip.beat,audio->left.size()/double(audio->rate));clip.audio=audio;clip.name=source.name+" · Bounce";lane.clips={clip};for(auto i=r.selection.rbegin();i!=r.selection.rend();i++)source.clips.erase(source.clips.begin()+i->second);int from=(int)p.tracks.size();p.tracks.push_back(std::move(lane));reorderTrack(p,from,r.track+1);p.bars=std::max(p.bars,barsForEnd(clip.beat+clip.length));return r.track+1;}
}
